from __future__ import annotations

import argparse
import json
import sys

from .core import (RESULTS, load_manifest, pack_path, pack_status, randomized_slots,
                   read_config, run_one, sha256, task_repo_names)
from .judge import judge_one
from .preflight import preflight
from .report import make_report


def main() -> int:
    parser = argparse.ArgumentParser(prog="agent_eval")
    sub = parser.add_subparsers(dest="command", required=True)
    for name in ("preflight", "run", "judge", "report", "reconcile-credits"):
        part = sub.add_parser(name)
        part.add_argument("--evaluation-id", required=True)
        if name == "preflight":
            part.add_argument("--cutoff")
            part.add_argument("--repo", action="append", default=[])
            part.add_argument("--live", action="store_true")
        elif name in ("run", "judge"):
            part.add_argument("--arm", action="append")
            part.add_argument("--task", action="append")
            if name == "run":
                part.add_argument("--full", action="store_true")
        elif name == "reconcile-credits":
            part.add_argument("--arm", required=True)
            part.add_argument("--task", required=True)
            part.add_argument("--billing-credits", required=True, type=float)
            part.add_argument("--billing-record-id", required=True)
    args = parser.parse_args()
    try:
        if args.command == "preflight":
            result = preflight(args.evaluation_id, args.cutoff, args.repo, args.live)
            print(json.dumps({"manifest": str(RESULTS / args.evaluation_id / "manifest.json"),
                              "arms": {key: value["status"] for key, value in result["preflight"].items()},
                              "judge": result["judge_preflight"]["status"],
                              "evidence": {key: value["status"] for key, value in result["evidence"].items()},
                              "repos": result["repos"]}, indent=2))
            return 0
        manifest = load_manifest(args.evaluation_id)
        arms = read_config("arms")["arms"]
        tasks = read_config("tasks")["tasks"]
        if args.command == "reconcile-credits":
            from .core import atomic_json
            if args.billing_credits < 0:
                raise ValueError("Billing credits must be nonnegative")
            if args.arm not in [a["id"] for a in arms if a["billing"] == "copilot"]:
                raise ValueError("Arm must use Copilot billing")
            if args.task not in [t["id"] for t in tasks]:
                raise ValueError("Unknown task")
            run_dir = RESULTS / args.evaluation_id / "runs" / args.task / args.arm
            if not (run_dir / "metrics.json").exists():
                raise ValueError("Run does not exist")
            path = run_dir / "credit-reconciliation.json"
            if path.exists():
                raise ValueError("Billing record already attached to this run")
            atomic_json(path, {"billing_credits": args.billing_credits,
                               "billing_record_id": args.billing_record_id,
                               "source": "GitHub billing record supplied by operator"})
            print(path)
            return 0
        if args.command in ("run", "judge"):
            selected_arms = [arm for arm in arms if not args.arm or arm["id"] in args.arm]
            selected_tasks = [task for task in tasks if not args.task or task["id"] in args.task]
            if not selected_arms or not selected_tasks:
                raise ValueError("No matching arms or tasks")
        if args.command == "run":
            if args.full and (args.arm or args.task):
                raise ValueError("--full cannot be combined with filters")
            if not args.full and not (args.arm or args.task):
                raise ValueError(f"Use --full for all {len(arms) * len(tasks)} slots, or select --arm/--task for a pilot")
            if manifest["judge_preflight"]["status"] != "ready":
                raise ValueError("Codex judge has not passed live preflight")
            for task in selected_tasks:
                okay, reason = pack_status(task["id"], manifest)
                if not okay:
                    raise ValueError(f"{task['id']}: {reason}")
                if manifest["evidence"][task["id"]]["sha256"] != sha256(pack_path(task["id"])):
                    raise ValueError(f"{task['id']}: evidence changed since live preflight")
                names = task_repo_names(task, manifest)
                if (task["repos"] and not names) or any(repo not in manifest["repos"] for repo in names):
                    raise ValueError(f"{task['id']}: missing pinned repo")
            if any(manifest["preflight"][arm["id"]]["status"] not in ("ready", "unavailable") for arm in selected_arms):
                raise ValueError("All selected arms must pass live preflight or be recorded unavailable")
            slots = randomized_slots(selected_tasks, selected_arms, read_config("run-policy")["seed"])
            from .core import atomic_json
            plan_path = RESULTS / args.evaluation_id / "run-plan.json"
            plan = {"seed": read_config("run-policy")["seed"],
                    "slots": [{"task_id": task["id"], "arm_id": arm["id"]} for task, arm in slots]}
            if plan_path.exists() and json.loads(plan_path.read_text()) != plan:
                raise ValueError("Run selection differs from the recorded run plan")
            if not plan_path.exists():
                atomic_json(plan_path, plan)
            for task, arm in slots:
                result = run_one(arm, task, manifest, args.evaluation_id)
                print(f"{task['id']} {arm['id']}: {result['status']}", flush=True)
            return 0
        if args.command == "judge":
            for task in selected_tasks:
                for arm in selected_arms:
                    result = judge_one(args.evaluation_id, task, arm, manifest)
                    if result:
                        print(f"{task['id']} {arm['id']}: {result['overall_quality']}/5", flush=True)
            return 0
        csv_path, report_path = make_report(args.evaluation_id, manifest)
        print(csv_path)
        print(report_path)
        return 0
    except (ValueError, RuntimeError, OSError, KeyError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import json
import tempfile
from pathlib import Path

from . import adapters
from .core import (RESULTS, ROOT, atomic_json, capture, config_hashes,
                   load_manifest, manifest_path, pack_status, read_config,
                   static_arm_check, utc_now, validate_cutoff, validate_repos)


PROBE = ("Use the tool named web_search to search for the official Python "
         "documentation page for pathlib Path. Then use the tool named web_fetch "
         "to fetch that result. Report the page title and URL. Both tool calls "
         "are required for this capability check.")


def _probe_failure(result: dict, answer: str) -> tuple[str, str | None]:
    """Classify known CLI failures without copying stderr or credentials to the manifest."""
    diagnostics: list[str] = []
    result_status = None
    for entry in result["events"]:
        data = entry.get("data")
        if not isinstance(data, dict):
            continue
        if entry.get("channel") == "stderr":
            diagnostics.append(str(data.get("raw_text", "")))
        if data.get("event") == "result" and isinstance(data.get("result"), dict):
            payload = data["result"]
            result_status = str(payload.get("status")) if payload.get("status") else None
            diagnostics.append(str(payload.get("error", "")))
    error_text = "\n".join(diagnostics).lower()
    if "resource_exhausted" in error_text or "individual quota reached" in error_text:
        return "Individual model quota reached (RESOURCE_EXHAUSTED)", result_status
    if "x509" in error_text or "certificate signed by unknown authority" in error_text:
        return "TLS certificate verification failed (x509)", result_status
    if result["timed_out"]:
        return "Live probe timed out", result_status
    if result_status and result_status != "SUCCESS":
        return f"Harness returned {result_status} during live probe", result_status
    if result["exit_code"] != 0:
        return f"Harness exited {result['exit_code']} during live probe", result_status
    if not answer:
        return "Live probe produced no final answer", result_status
    return "Live probe failed", result_status


def _judge_probe(directory: Path, timeout: int) -> dict:
    schema = directory / "probe-schema.json"
    schema.write_text(json.dumps({"type": "object", "additionalProperties": False,
                                  "required": ["ok"], "properties": {"ok": {"type": "boolean"}}}))
    output = directory / "probe-output.json"
    cmd = ["codex", "exec", "--model", "gpt-6-sol", "--ephemeral",
           "--sandbox", "read-only", "--skip-git-repo-check", "--ignore-user-config",
           "--output-schema", str(schema), "--output-last-message", str(output),
           "Reply with JSON containing ok=true."]
    try:
        import os
        result = capture(cmd, directory, os.environ.copy(), timeout, directory / "judge-probe-events.jsonl")
        payload = json.loads(output.read_text()) if output.exists() else None
        return {"status": "ready" if result["exit_code"] == 0 and payload == {"ok": True} else "failed",
                "reason": None if payload == {"ok": True} else "Codex did not return schema-conforming JSON",
                "version": _version("codex")}
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return {"status": "failed", "reason": str(exc), "version": _version("codex")}


def _version(binary: str) -> str | None:
    import subprocess
    try:
        return subprocess.check_output([binary, "--version"], text=True, timeout=10).strip()
    except (OSError, subprocess.SubprocessError):
        return None


def live_arm_probe(arm: dict, timeout: int) -> dict:
    with tempfile.TemporaryDirectory(prefix="agent-eval-probe-") as temporary:
        directory = Path(temporary)
        run_dir = directory / "run"
        run_dir.mkdir()
        command = adapters.command(arm, PROBE, directory, run_dir)
        if arm["harness"] == "copilot":
            import uuid
            command[command.index("--session-id") + 1] = str(uuid.uuid4())
        env = adapters.environment(arm, directory)
        try:
            result = capture(command, directory, env, timeout, directory / "events.jsonl")
        except OSError as exc:
            return {"status": "unavailable", "reason": str(exc)}
        answer = adapters.final_answer(arm["harness"], result["events"])
        names = (adapters.completed_claude_tool_names(result["events"])
                 if arm["harness"] == "claude" else adapters.tool_names(result["events"]))
        search = any(any(word in name.lower() for word in ("web_search", "websearch", "search_web")) for name in names)
        fetch = any(any(word in name.lower() for word in ("fetch", "webpage", "browse", "open_url", "read_url_content")) for name in names)
        if result["exit_code"] or result["timed_out"] or not answer:
            reason, result_status = _probe_failure(result, answer)
            return {"status": "unavailable", "reason": reason,
                    "probe_exit_code": result["exit_code"],
                    "probe_timed_out": result["timed_out"],
                    "probe_result_status": result_status,
                    "probe_answer_present": bool(answer), "probe_tool_names": names}
        if not (search and fetch):
            return {"status": "unavailable", "reason": "Search and page fetch were not both observed in headless events",
                    "probe_tool_names": names}
        usage = adapters.usage(arm["harness"], result["events"], run_dir)
        return {"status": "ready", "reason": None, "probe_tool_names": names,
                "usage_fields": sorted(usage["raw"].keys()) if isinstance(usage["raw"], dict) else [],
                "usage_classification": usage["classification"]}


def preflight(evaluation_id: str, cutoff: str | None, repo_args: list[str],
              live: bool) -> dict:
    def same_pin(left: dict, right: dict) -> bool:
        return left["path"] == right["path"] and left["commit"] == right["commit"]

    path = manifest_path(evaluation_id)
    if path.exists():
        manifest = load_manifest(evaluation_id)
        if any((RESULTS / evaluation_id / "runs").rglob("metrics.json")):
            raise ValueError("Cannot modify preflight after runs begin")
        if cutoff and validate_cutoff(cutoff) != manifest["cutoff"]:
            raise ValueError("Cutoff differs from existing manifest")
        if repo_args:
            repos = validate_repos(repo_args)
            for name, info in repos.items():
                if name in manifest["repos"] and not same_pin(manifest["repos"][name], info):
                    raise ValueError("Repository pin differs from existing manifest")
            manifest["repos"].update(repos)
    else:
        if not cutoff:
            raise ValueError("A new evaluation requires --cutoff")
        repos = validate_repos(repo_args)
        manifest = {"evaluation_id": evaluation_id, "created_at": utc_now(),
                    "cutoff": validate_cutoff(cutoff), "config_hashes": config_hashes(),
                    "repos": repos, "preflight": {},
                    "judge_preflight": {"status": "needs_live_probe"}}
    arms = read_config("arms")["arms"]
    tasks = read_config("tasks")["tasks"]
    for arm in arms:
        state = static_arm_check(arm)
        if live and state["status"] == "needs_live_probe":
            state.update(live_arm_probe(arm, read_config("run-policy")["probe_timeout_seconds"]))
        manifest["preflight"][arm["id"]] = state
    manifest["evidence"] = {task["id"]: {"status": pack_status(task["id"], manifest)[1],
                                        "sha256": None} for task in tasks}
    if live:
        from .core import sha256, pack_path
        for task in tasks:
            if pack_status(task["id"], manifest)[0]:
